export const SPRITE_WORKSHOP_PRESETS_ATLAS: SpriteWorkshopPreset[] = SPECS.map((s): SpriteWorkshopPreset => ({
  id: s.id,
  name: s.name,
  role: s.role,
  category: s.category,
  archetype: s.archetype,
  voicePreset: s.voicePreset,
  tagline: s.tagline,
  dna: createBaseDna(s.chassis, {
    outfit: {
      topStyle: s.top,
      headwear: s.head,
      surfacePattern: s.pat,
    },
    appendages: {
      ...(s.wings ? { wings: s.wings } : {}),
      ...(s.tail ? { tail: s.tail } : {}),
      ...(s.aura ? { aura: s.aura } : {}),
    },
    palette: {
      primary: s.primary,
      secondary: s.secondary,
      accent: s.accent,
      skin: s.skin,
      hair: s.hair || '#18181b',
      eye: '#f8fafc',
      patternTint: s.accent,
    },
  }),
}));
